const inp = $input.first().json;
const REQUIRED = ['userId','sessionId','remoteJid','instance'];
const missing  = REQUIRED.filter(k => !inp[k]);
if (missing.length) {
  return [{ json: { success: false, error: 'MISSING_FIELDS', details: missing, original: inp } }];
}
return [{ json: { success: true, ...inp } }];

// Carga datos del KB solo si procedure_key ya existe en el contexto
// (fue seleccionado en un mensaje anterior).
// Si no existe, devuelve __skip__ para que db_manager retorne vacío gracefully.
const ctx  = $input.first().json.sessionContext || {};
const sage = ctx.sage || {};
const key  = sage.procedure_key || null;

if (!key) {
  // No hay procedimiento seleccionado aún — skip DB call
  return [{ json: { operation: '__skip__', params: {} } }];
}
return [{ json: { operation: 'getProcedure', params: { procedureKey: key } } }];

// ============================================================
// SAGE v1.0.0 — Especialista en Cotizaciones Médicas
// Sistema NOVA · SAGE · ATLAS + WhatsApp
// Erick Del Piero | Marzo 2026
//
// MOTOR DE ESTADO:
//   welcome / handoff_received → Bienvenida + selección de especialidad
//   selecting_specialty        → Detecta especialidad y muestra lista de procedimientos
//   selecting_procedure        → Usuario elige procedimiento, guarda key en ctx
//   procedure_confirmed        → KB data disponible, inicia Q&A
//   questioning                → Pregunta y guarda respuestas secuencialmente
//   summary                    → Muestra resumen + score de completitud
//   complete                   → Intake enviado, ofrece ATLAS
//
// DISEÑO PARA CLAUDE UPGRADE:
// Los estados 'questioning' y 'summary' serán reemplazados por
// llamadas a Claude API que extraerán datos con NLP y generarán
// respuestas conversacionales más naturales. El resto del estado
// machine permanece igual.
// ============================================================

const inp            = $('🔍 Validar Input SAGE').first().json;
const procedureResult = $input.first().json; // resultado de DB — Cargar Procedimiento

// ── SETUP ──────────────────────────────────────────────────
const ctx  = inp.sessionContext || {};
const sage = { ...(ctx.sage || {}) };
const state = sage.state || 'welcome';
const txt  = (inp.messageText || '').toLowerCase().trim();
const fn   = inp.userName ? inp.userName.split(' ')[0] : null;
const nm   = fn ? ` ${fn}` : '';

// Datos del KB (disponibles si procedure_key estaba en ctx al inicio del mensaje)
const parseArr = (v) => {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  try { return JSON.parse(v); } catch(e) { return []; }
};
const procData = (procedureResult.success && procedureResult.data && procedureResult.data.length > 0)
  ? procedureResult.data[0] : null;

// Lista de procedimientos hardcodeada (sincronizada con KB en DB)
// Evita round-trips innecesarios para mostrar el menú de selección.
const PROCEDURES = {
  dental: [
    { name: 'Extracción Simple',             key: 'extraccion_simple'    },
    { name: 'Extracción Muela del Juicio',    key: 'extraccion_muela_juicio' },
    { name: 'Implante Dental',               key: 'implante_dental'     },
    { name: 'Prótesis Dental Completa',      key: 'protesis_completa'   },
    { name: 'Carillas / Veneers',            key: 'carillas_veneers'    },
    { name: 'Ortodoncia Brackets',           key: 'ortodoncia_brackets' },
    { name: 'Ortodoncia Invisible',          key: 'ortodoncia_invisible'},
    { name: 'Endodoncia (Conducto)',         key: 'endodoncia'          },
    { name: 'Corona Dental',                 key: 'corona_dental'       },
    { name: 'Limpieza Profunda (Periodoncia)', key: 'limpieza_profunda'  },
    { name: 'Blanqueamiento Dental',         key: 'blanqueamiento'      },
    { name: 'Puente Dental',                 key: 'puente_dental'       }
  ],
  plastic_surgery: [
    { name: 'Rinoplastia',                   key: 'rinoplastia'         },
    { name: 'Abdominoplastia',               key: 'abdominoplastia'     },
    { name: 'Liposucción',                   key: 'liposuccion'         },
    { name: 'Aumento de Busto',              key: 'aumento_mamario'     },
    { name: 'Reducción de Busto',            key: 'reduccion_mamaria'   },
    { name: 'Bichectomía',                   key: 'bichectomia'         },
    { name: 'Blefaroplastia (Párpados)',      key: 'blefaroplastia'      },
    { name: 'Otoplastia (Orejas)',            key: 'otoplastia'          },
    { name: 'Lifting Facial',                key: 'lifting_facial'      },
    { name: 'BBL (Brazilian Butt Lift)',      key: 'bbl'                 }
  ]
};

let rt  = '';         // responseText
let nag = 'SAGE';    // newActiveAgent
let nss = 'sage_active'; // newSessionState
let shouldSaveIntake = false;
let intakePayload    = null;

switch(state) {

  // ── BIENVENIDA ─────────────────────────────────────────────
  case 'welcome':
  case 'handoff_received': {
    rt = `Hola${nm}, soy *SAGE* 🩺 tu especialista en cotizaciones médicas de Pangi.\n\nMi trabajo es preparar tu solicitud para que los médicos puedan darte precios *precisos*. Mientras más información des, mejores cotizaciones recibirás.\n\nPrimero dime: *¿Para qué especialidad necesitas cotizar?*\n\n🦷 Escribe *1* o *dental*\n💉 Escribe *2* o *cirugía plástica*`;
    sage.state = 'selecting_specialty';
    break;
  }

  // ── SELECCIÓN DE ESPECIALIDAD ──────────────────────────────
  case 'selecting_specialty': {
    const kDental   = /dental|diente|muela|implante|ortodoncia|corona|carilla|veneer|blanquea|endodoncia|extrac|puente|prótesis|protesis|limpieza|conducto/i;
    const kPlastic  = /plastic|cirugía|cirugia|rinoplas|liposu|abdominoplas|mamario|busto|seno|bichec|blefaroplas|otoplas|lifting|bbl|nariz|glút|glut/i;
    const isDental  = kDental.test(txt) || txt === '1';
    const isPlastic = kPlastic.test(txt) || txt === '2';

    if (!isDental && !isPlastic) {
      rt = `No reconocí la especialidad${nm} 😅\n\nPor favor elige una opción:\n🦷 Escribe *1* o *dental*\n💉 Escribe *2* o *cirugía plástica*`;
      // Mantener estado
      break;
    }

    const sp    = isDental ? 'dental' : 'plastic_surgery';
    const emoji = isDental ? '🦷' : '💉';
    const procs = PROCEDURES[sp];
    const list  = procs.map((p, i) => `${i + 1}. ${p.name}`).join('\n');

    sage.specialty = sp;
    rt = `${emoji} Perfecto. ¿Sobre qué procedimiento específico deseas cotizar?\n\n${list}\n\nEscribe el número o el nombre del procedimiento.`;
    sage.state = 'selecting_procedure';
    break;
  }

  // ── SELECCIÓN DE PROCEDIMIENTO ─────────────────────────────
  case 'selecting_procedure': {
    const sp    = sage.specialty || 'dental';
    const procs = PROCEDURES[sp] || [];
    let matched = null;

    // Match por número
    const num = parseInt(txt);
    if (!isNaN(num) && num >= 1 && num <= procs.length) {
      matched = procs[num - 1];
    }
    // Match por nombre completo o key
    if (!matched) {
      matched = procs.find(p =>
        txt.includes(p.name.toLowerCase()) ||
        txt.includes(p.key.replace(/_/g, ' '))
      );
    }
    // Match flexible (al menos 1 palabra significativa)
    if (!matched) {
      matched = procs.find(p => {
        const words = p.name.toLowerCase().split(' ').filter(w => w.length > 4);
        return words.some(w => txt.includes(w));
      });
    }

    if (!matched) {
      const emoji = sp === 'dental' ? '🦷' : '💉';
      const list  = procs.map((p, i) => `${i + 1}. ${p.name}`).join('\n');
      rt = `No encontré ese procedimiento${nm}. Por favor elige de la lista:\n\n${emoji} *Procedimientos disponibles:*\n${list}`;
      // Mantener estado
      break;
    }

    sage.procedure_key  = matched.key;
    sage.procedure_name = matched.name;
    sage.state          = 'procedure_confirmed';

    rt = `*${matched.name}* ✅\n\nVoy a hacerte algunas preguntas para preparar tu solicitud. Mientras más detalles des, más precisas serán las cotizaciones que recibirás.\n\nEscribe *listo* o cualquier cosa para empezar.`;
    break;
  }

  // ── PROCEDIMIENTO CONFIRMADO — espera datos del KB ─────────
  // En este estado, procedure_key ya está en ctx.
  // En ESTE mensaje el KB ya fue cargado desde DB (procedure_key existía al inicio).
  case 'procedure_confirmed': {
    if (!procData) {
      // KB aún no disponible — situación de borde, reintentar
      rt = `Preparando tu formulario${nm}... un momento 🩺`;
      break; // Mantener estado
    }

    const questions = parseArr(procData.critical_questions);
    const infoKeys  = parseArr(procData.required_info);

    // Guardar KB data en contexto para no volver a consultarla
    sage.critical_questions  = questions;
    sage.required_info       = infoKeys;
    sage.required_exams      = parseArr(procData.required_exams);
    sage.typical_recovery    = procData.typical_recovery_days || 3;
    sage.collected_data      = {};
    sage.current_q_index     = 1; // Mostraremos pregunta[0] ahora
    sage.state               = 'questioning';

    const intro = procData.sage_intro_message || `Empecemos con *${sage.procedure_name}*:`;
    rt = `${intro}\n\n*Pregunta 1 de ${questions.length}:*\n${questions[0]}`;

    // Crear el intake en DB
    shouldSaveIntake = true;
    intakePayload = {
      operation: 'saveMedicalIntake',
      params: {
        userId:        inp.userId,
        sessionId:     inp.sessionId,
        specialty:     sage.specialty,
        procedureName: sage.procedure_name,
        collectedData: {},
        missingItems:  sage.required_exams,
        score:         0
      }
    };
    break;
  }

  // ── Q&A — PREGUNTAS SECUENCIALES ───────────────────────────
  case 'questioning': {
    const questions  = sage.critical_questions || [];
    const infoKeys   = sage.required_info      || [];
    const currentIdx = sage.current_q_index    || 1;
    const collected  = { ...(sage.collected_data || {}) };
    const totalQ     = questions.length;

    // Guardar respuesta a la pregunta anterior
    // current_q_index = N significa que ya mostramos N preguntas.
    // La respuesta actual corresponde a infoKeys[N-1] (la última mostrada).
    if (infoKeys[currentIdx - 1]) {
      collected[infoKeys[currentIdx - 1]] = inp.messageText;
    }
    sage.collected_data = collected;

    const answeredCount = Object.keys(collected).length;
    const baseScore     = Math.round((answeredCount / totalQ) * 85);
    const examBonus     = (sage.required_exams || []).some(exam =>
      txt.includes(exam.replace(/_/g, ' ').toLowerCase().substring(0, 5))
    ) ? 15 : 0;
    const score = Math.min(100, baseScore + examBonus);
    sage.completeness_score = score;

    if (currentIdx >= totalQ) {
      // TODAS las preguntas respondidas → ir a resumen
      sage.current_q_index = currentIdx;
      sage.state = 'summary';

      const summaryLines = Object.entries(collected)
        .map(([k, v]) => `✅ *${k.replace(/_/g, ' ')}:* ${v}`)
        .join('\n');

      const examsList = (sage.required_exams || []).length > 0
        ? `\n\n📋 *Exámenes recomendados para llevar:*\n${(sage.required_exams || []).map(e => `• ${e.replace(/_/g, ' ')}`).join('\n')}`
        : '';

      const scoreLabel = score >= 80
        ? '🟢 Excelente — Recibirás cotizaciones muy precisas'
        : score >= 60
          ? '🟡 Buena — Cotizaciones bastante precisas'
          : '🔴 Básica — Considera agregar más detalles';

      rt = `¡Listo${nm}! Tu solicitud de *${sage.procedure_name}* está preparada 🎉\n\n*Resumen de tu caso:*\n${summaryLines}${examsList}\n\n📊 *Completitud: ${score}%* — ${scoreLabel}\n\nEscribe *confirmar* para publicar tu solicitud y comenzar a recibir cotizaciones de médicos.\nO agrega más información para subir el score.`;

      shouldSaveIntake = true;
      intakePayload = {
        operation: 'updateMedicalIntake',
        params: {
          intakeId:     sage.intake_id,
          collectedData: collected,
          missingItems:  sage.required_exams,
          score,
          status:       'in_progress'
        }
      };
    } else {
      // Mostrar siguiente pregunta
      sage.current_q_index = currentIdx + 1;
      const progress = `_Pregunta ${currentIdx + 1} de ${totalQ} · Completitud: ${score}%_`;
      rt = `*${questions[currentIdx]}*\n\n${progress}`;

      shouldSaveIntake = true;
      intakePayload = {
        operation: 'updateMedicalIntake',
        params: {
          intakeId:     sage.intake_id,
          collectedData: collected,
          missingItems:  sage.required_exams,
          score
        }
      };
    }
    break;
  }

  // ── RESUMEN — CONFIRMAR ENVÍO ───────────────────────────────
  case 'summary': {
    const isConfirm = /confirm|sí|si|yes|enviar|publicar|listo|ok|dale|adelante/i.test(txt);

    if (isConfirm) {
      rt  = `✅ *¡Solicitud publicada${fn ? ', ' + fn : ''}!*\n\nTu solicitud de *${sage.procedure_name}* ya está visible para los médicos de Pangi.\n\n⏱️ *Tiempo estimado de respuesta:* 24-48 horas\n\n*¿Qué sigue?*\nCuando recibas cotizaciones de distintos destinos, *ATLAS* puede calcular el costo total real de cada opción considerando vuelo, alojamiento y días de recuperación.\n\n¿Quieres que te conecte con ATLAS ahora para explorar destinos?`;
      sage.state = 'complete';
      shouldSaveIntake = true;
      intakePayload = {
        operation: 'updateMedicalIntake',
        params: {
          intakeId: sage.intake_id,
          status:   'submitted',
          score:    sage.completeness_score || 0
        }
      };
    } else {
      // Usuario quiere agregar más información
      const prev = sage.collected_data || {};
      prev['detalle_adicional'] = inp.messageText;
      sage.collected_data = prev;
      const newScore = Math.min(100, (sage.completeness_score || 70) + 8);
      sage.completeness_score = newScore;
      rt = `Perfecto${nm}, agregué esos detalles a tu solicitud 📋\n\n📊 *Completitud actualizada: ${newScore}%*\n\nCuando estés listo/a, escribe *confirmar* para publicar.`;
      shouldSaveIntake = true;
      intakePayload = {
        operation: 'updateMedicalIntake',
        params: {
          intakeId:     sage.intake_id,
          collectedData: prev,
          score:         newScore
        }
      };
    }
    break;
  }

  // ── COMPLETO — OFRECER ATLAS ────────────────────────────────
  case 'complete': {
    const wantsAtlas = /atlas|compar|destino|sí|si|yes|quiero|dale|adelante/i.test(txt);
    if (wantsAtlas) {
      rt  = `¡Perfecto${nm}! Te conecto con *ATLAS* 🗺️, nuestro consejero de turismo médico.\n\nYa le compartí tu solicitud de *${sage.procedure_name}*. Él calculará el costo total real de cada destino.`;
      nag = 'ATLAS';
      nss = 'handoff_received';
      sage.state = 'handoff_to_atlas';
    } else {
      rt = `Entendido${nm}. Cuando quieras comparar destinos, escribe *comparar* y te conecto con ATLAS 🗺️\n\n¿Necesitas ayuda con algo más?`;
      sage.state = 'waiting_for_quotes';
    }
    break;
  }

  // ── FALLBACK ────────────────────────────────────────────────
  default: {
    rt = `Hola${nm}, soy *SAGE* 🩺 tu especialista en cotizaciones. Escribe cualquier cosa para empezar.`;
    sage.state = 'welcome';
  }
}

// ── RESULTADO ──────────────────────────────────────────────
return [{ json: {
  success:          true,
  responseText:     rt,
  newActiveAgent:   nag,
  newSessionState:  nss,
  newSageContext:   sage,
  inputContext:     ctx,
  shouldSaveIntake,
  intakePayload:    intakePayload || null,
  userId:           parseInt(inp.userId),
  sessionId:        parseInt(inp.sessionId),
  userLanguage:     inp.userLanguage || 'es',
  userName:         inp.userName    || null,
  remoteJid:        inp.remoteJid,
  instance:         inp.instance
}}];

// Prepara el payload para save o update del intake médico.
// Si shouldSaveIntake=false, devuelve __skip__ para saltar la DB call.
const motor = $input.first().json;

if (!motor.shouldSaveIntake || !motor.intakePayload) {
  // No hay intake que guardar en este mensaje
  return [{ json: { operation: '__skip__', params: {}, _motorOutput: motor } }];
}

// Si el intake ya existe (intake_id en contexto), aseguramos que el payload sea update
const sage = motor.newSageContext || {};
if (motor.intakePayload.operation === 'updateMedicalIntake' && !sage.intake_id) {
  // Todavía no tenemos el intake_id (raro edge case) — skip
  return [{ json: { operation: '__skip__', params: {}, _motorOutput: motor } }];
}

return [{ json: { ...motor.intakePayload, _motorOutput: motor } }];

// ============================================================
// Construye la respuesta final de SAGE.
// Extrae intake_id de la DB si el intake fue creado ahora.
// Ensambla newSessionContext con el sage context actualizado.
// ============================================================

const dbResult   = $input.first().json;         // resultado del DB save/update
const prepNode   = $('📦 Preparar — Guardar Intake').first().json;
const motorOutput = prepNode._motorOutput || dbResult._motorOutput;

if (!motorOutput) {
  return [{ json: {
    success: false,
    error:   'MOTOR_OUTPUT_LOST',
    responseText: 'Error interno. Por favor escribe de nuevo.',
    newActiveAgent: 'SAGE'
  }}];
}

// Actualizar intake_id si el intake fue recién creado
const sageCtx = { ...motorOutput.newSageContext };
const wasNewIntake = motorOutput.intakePayload && motorOutput.intakePayload.operation === 'saveMedicalIntake';
if (wasNewIntake && dbResult.success && dbResult.data && dbResult.data[0]) {
  sageCtx.intake_id = dbResult.data[0].id;
}

// Construir newSessionContext preservando otros agentes en el contexto
const newSessionContext = {
  ...(motorOutput.inputContext || {}),
  sage: sageCtx
};

return [{ json: {
  success:            true,
  responseText:       motorOutput.responseText,
  newActiveAgent:     motorOutput.newActiveAgent  || 'SAGE',
  newSessionState:    motorOutput.newSessionState || 'sage_active',
  newSessionContext,
  userId:             motorOutput.userId,
  sessionId:          motorOutput.sessionId,
  userLanguage:       motorOutput.userLanguage    || 'es',
  userName:           motorOutput.userName        || null,
  remoteJid:          motorOutput.remoteJid,
  instance:           motorOutput.instance
}}];

const e = $input.first().json;
return [{ json: {
  success:        false,
  error:          e.error   || 'SAGE_ENGINE_ERROR',
  details:        e.details || [],
  responseText:   'Lo siento, tuve un problema técnico. Por favor escribe de nuevo en unos momentos.',
  newActiveAgent: 'SAGE',
  _meta: { timestamp: new Date().toISOString(), source: 'sage_error' }
}}];
